centers=[(3,6,8),(4,13,4),(12,14,1),(14,3,2)]
for r,c,v in centers:
    G[r][c]=v
    for rr,cc in [(r-1,c),(r+1,c),(r,c-1),(r,c+1)]: G[rr][cc]=3
# fill horizontal zeros then vertical zeros, vertical overwrites horizontal fills
O=[row[:] for row in G]
for r,c,v in centers:
    for cc in range(W):
        if O[r][cc]==0: O[r][cc]=v
for r,c,v in centers:
    for rr in range(H):
        if O[rr][c]==0 or (O[rr][c] in [x[2] for x in centers] and G[rr][c]==0 and rr!=r):
            # Need vertical override horizontal color only, not existing color lines from vertical other center; columns distinct, no overlap.
            O[rr][c]=v
print('\n'.join(' '.join(map(str,row)) for row in O))

H=W=19
G=[[0]*W for _ in range(H)]
centers=[(3,6,8),(4,13,4),(12,14,1),(14,3,2)]
owned={}
for r,c,v in centers:
    G[r][c]=v
    for rr,cc in [(r-1,c),(r+1,c),(r,c-1),(r,c+1)]:
        G[rr][cc]=3; owned.setdefault((rr,cc),set()).add((r,c))
# original plus arms list, and barrier for a source iff original 3 not in that source's arms
base=[row[:] for row in G]
O=[row[:] for row in G]
for r,c,v in centers:
    for dc in (-1,1):
        cc=c+dc
        while 0<=cc<W:
            if base[r][cc]==3 and (r,cc) not in [(r,c-1),(r,c+1),(r-1,c),(r+1,c)]: break
            if O[r][cc]==0: O[r][cc]=v
            cc+=dc
for r,c,v in centers:
    for dr in (-1,1):
        rr=r+dr
        while 0<=rr<H:
            if base[rr][c]==3 and (rr,c) not in [(r,c-1),(r,c+1),(r-1,c),(r+1,c)]: break
            # vertical line overwrite previous horizontal fill if not original object 3
            if base[rr][c]==0: O[rr][c]=v
            rr+=dr
print('\n'.join(' '.join(map(str,row)) for row in O))
